use serde::{Deserialize, Serialize};

use crate::{EventModelDataTransfer, EventModelError};

use self::{v0_1_0_beta::JsonV0_1_0BetaTransfer, v1_0_0::JsonV1_0_0Transfer};

mod v0_1_0_beta;
mod v1_0_0;

pub fn as_string(option: Option<String>) -> String {
    match option {
        Some(s) => s,
        None => String::default(),
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "spec-version", content = "event-model")]
pub enum JsonImport {
    #[serde(rename = "0.1.0-beta")]
    V0_1_0Beta(JsonV0_1_0BetaTransfer),

    #[serde(rename = "1.0.0")]
    V1_0_0(JsonV1_0_0Transfer),
}

impl TryFrom<JsonImport> for EventModelDataTransfer {
    type Error = EventModelError;

    fn try_from(value: JsonImport) -> Result<Self, Self::Error> {
        match value {
            JsonImport::V0_1_0Beta(transfer) => transfer.try_into(),
            JsonImport::V1_0_0(_) => todo!(),
        }
    }
}

pub fn import(json: &[u8]) -> Result<JsonImport, serde_json::Error> {
    serde_json::from_slice(json)
}

#[derive(Debug, Clone, Serialize)]
pub enum JsonExport {
    V1_0_0(JsonV1_0_0Transfer),
}

pub fn export(_model: &JsonExport) -> String {
    todo!()
}

